<?php $e=static fn(mixed $v):string=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); ?>
<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Community-Freigabe – MeldeVerkehr</title><style>body{font-family:system-ui,sans-serif;background:#f5f7fa;color:#172033;margin:0}main{max-width:900px;margin:28px auto;padding:20px}.card{background:#fff;border:1px solid #dfe5ec;border-radius:15px;padding:20px;margin-bottom:14px}.warn{padding:11px;border:1px solid #d6b36b;background:#fffaf0;border-radius:8px}.message,.error{padding:10px;border-radius:8px}.message{border:1px solid #8fb799}.error{border:1px solid #c99}textarea,select{width:100%;box-sizing:border-box;padding:9px;border:1px solid #bac5d1;border-radius:8px}button,.button{display:inline-block;padding:9px 13px;border:0;border-radius:9px;background:#172033;color:#fff;text-decoration:none;font-weight:700;margin-top:8px}.danger{background:#8e1f1f}.release{border-top:1px solid #e5e9ee;padding:12px 0}.hash{font-family:ui-monospace,monospace;font-size:.8rem;word-break:break-all}</style></head><body><main><p><a href="/cases/<?= rawurlencode($caseId) ?>">← Vorgang</a></p><h1>Kontrollierte Community-Freigabe</h1><div class="warn"><strong>Wichtig:</strong> Es wird eine separate öffentliche Kopie erstellt. Die private Akte bleibt unverändert. Bilder sind nur auswählbar, wenn eine bestätigte Privacy-PUBLIC-Version existiert.</div><?php if($message):?><div class="message"><?= $e($message) ?></div><?php endif;?><?php if($error):?><div class="error"><?= $e($error) ?></div><?php endif;?>
<section class="card"><h2>Neue Freigabekopie</h2><form method="post" action="/cases/<?= rawurlencode($caseId) ?>/community-release"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><label>Öffentlicher Text</label><textarea name="public_text" maxlength="5000" rows="5"></textarea><label>Standortfreigabe</label><select name="location_level"><option value="NONE">Kein Standort</option><option value="CITY">Nur Ort/Region</option><option value="STREET">Straße ohne Hausnummer</option></select><p><label><input type="checkbox" name="include_date" value="1"> Beobachtungsdatum (nur Datum)</label><br><label><input type="checkbox" name="include_offense" value="1"> bestätigten Tatbestand</label></p><h3>Redigierte Bilder</h3><?php foreach($availableEvidence as $img):?><label><input type="checkbox" name="evidence_ids[]" value="<?= $e($img['id']) ?>"> <?= $e($img['category']) ?> · <?= $e($img['original_filename']) ?> · PUBLIC v<?= $e($img['public_version_no']) ?></label><br><?php endforeach;?><button type="submit">Öffentliche Kopie als Entwurf erzeugen</button></form></section>
<section class="card"><h2>Freigaben</h2><?php foreach($releases as $r):?><div class="release"><strong><?= $e($r['status']) ?></strong> · <?= $e($r['created_at']) ?><p class="hash"><?= $e($r['snapshot_sha256']) ?></p><?php if($r['status']==='DRAFT'):?><form method="post" action="/community/releases/<?= rawurlencode($r['id']) ?>/publish"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><input type="hidden" name="case_id" value="<?= $e($caseId) ?>"><button type="submit">Veröffentlichen</button></form><?php elseif($r['status']==='PUBLISHED'):?><a class="button" href="/community/releases/<?= rawurlencode($r['public_token']) ?>">Öffentliche Kopie ansehen</a><form method="post" action="/community/releases/<?= rawurlencode($r['id']) ?>/withdraw"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><input type="hidden" name="case_id" value="<?= $e($caseId) ?>"><button class="danger" type="submit">Zurückziehen</button></form><?php endif;?></div><?php endforeach;?></section>
</main></body></html>